\begin{ex}%[9X8H2-2]
\immini[thm]{
Trong trò chơi "Vòng quay may mắn", bánh xe hình tròn chia thành $8$ hình quạt bằng nhau đánh số từ $1$ đến $8$: các ô {1, 3, 5} sơn màu Đỏ, các ô {2, 4, 6, 8} sơn màu Xanh, riêng ô số $7$ sơn màu Vàng (như hình vẽ). Thực hiện quay ngẫu nhiên, xét tính đúng sai của các khẳng định sau:
\choiceTF
{Xác suất quay $1$ lần trúng ô màu Đỏ là $50\%$}
  {Xác suất trúng ô mang số nguyên tố bằng với xác suất trúng ô mang hợp số}
  {Xác suất để quay $1$ lần trúng ô màu Đỏ hoặc ô có số chia hết cho $3$ là $\dfrac{1}{4}$}
  {Khi quay $2$ lần liên tiếp, xác suất có ít nhất một lần trúng ô màu Vàng là $\dfrac{1}{4}$}
}{
\begin{tikzpicture}[scale=0.62, line cap=round, line join=round, font=\scriptsize]
\fill[gray!40] (-1.3,-3.3) rectangle (1.3,-2.7);
\fill[gray!60] (-1.0,-2.7) -- (1.0,-2.7) -- (0,-0.4) -- cycle;
\draw[thick, fill=white] (0,0) circle (2.3);
\foreach \i/\col/\tc in {1/red!80!black/white, 2/green!55!black/white, 3/red!80!black/white, 4/green!55!black/white, 5/red!80!black/white, 6/green!55!black/white, 7/yellow!85!orange/black, 8/green!55!black/white} {
  \fill[\col] (0,0) -- ({-45*(\i-1)+112.5}:2.3) arc ({-45*(\i-1)+112.5}:{-45*\i+112.5}:2.3) -- cycle;
  \draw[thick, white] (0,0) -- ({-45*\i+112.5}:2.3);
  \node[font=\bfseries, text=\tc] at ({-45*(\i-1)+90}:1.45) {\i};
}
\fill[white] (0,0) circle (0.3); \draw[thick] (0,0) circle (0.3) circle (2.3);
\fill[orange] (-0.28,2.4) -- (0.28,2.4) -- (0,2.9) -- cycle;
\end{tikzpicture}
}
\loigiai{
\begin{itemchoice}
\itemch Có $3$ ô màu Đỏ trên tổng số $8$ ô nên xác suất là $\dfrac{3}{8} = 37{,}5\%$.
\itemch Các số nguyên tố là $\{2;3;5;7\}$ (4 số), hợp số là $\{4;6;8\}$ (3 số), nên $\dfrac{4}{8} > \dfrac{3}{8}$.
\itemch Tập hợp các ô thuận lợi là ${1, 3, 5, 6}$ gồm $4$ ô, xác suất là $\dfrac{1}{2}$.
\itemch Xác suất cả $2$ lần không trúng ô Vàng là $\left(\dfrac{7}{8}\right)^2 = \dfrac{49}{64}$, suy ra xác suất biến cố đối là $1 - \dfrac{49}{64} = \dfrac{15}{64}$.
\end{itemchoice}
}\end{ex}

